import type {Schema} from '@portabletext/schema'
import {isTextBlock, type PortableTextObject} from '@portabletext/schema'
import type {
  ArbitraryTypedObject,
  HtmlParser,
  MinimalBlock,
  MinimalSpan,
  PlaceholderAnnotation,
  PlaceholderDecorator,
  TypedObject,
} from '../types'
import {DEFAULT_BLOCK} from './constants'
import {resolveJsType} from './resolve-js-type'

/**
 * Utility function that always return a lowerCase version of the element.tagName
 *
 * @param el - Element to get tag name for
 * @returns Lowercase tagName for that element, or undefined if not an element
 */
export function tagName(el: HTMLElement | Node | null): string | undefined {
  if (el && 'tagName' in el) {
    return el.tagName.toLowerCase()
  }

  return undefined
}

/**
 * A default `parseHtml` function that returns the html using `DOMParser`.
 *
 * @returns HTML Parser based on `DOMParser`
 */
export function defaultParseHtml(): HtmlParser {
  if (resolveJsType(DOMParser) === 'undefined') {
    throw new Error(
      'The native `DOMParser` global which the `Html` deserializer uses by ' +
        'default is not present in this environment. ' +
        'You must supply the `options.parseHtml` function instead.',
    )
  }
  return (html) => {
    return new DOMParser().parseFromString(html, 'text/html')
  }
}

export function ensureRootIsBlocks(
  schema: Schema,
  objects: Array<ArbitraryTypedObject>,
): ArbitraryTypedObject[] {
  return objects.reduce((blocks, node, i, original) => {
    if (node._type === 'block') {
      blocks.push(node)
      return blocks
    }

    if (node._type === '__block') {
      blocks.push((node as any).block)
      return blocks
    }

    const lastBlock = blocks[blocks.length - 1]
    if (
      i > 0 &&
      !isTextBlock({schema}, original[i - 1]) &&
      isTextBlock({schema}, lastBlock)
    ) {
      lastBlock.children.push(node as PortableTextObject)
      return blocks
    }

    const block = {
      ...DEFAULT_BLOCK,
      children: [node],
    }

    blocks.push(block)
    return blocks
  }, [] as ArbitraryTypedObject[])
}

export function isNodeList(node: unknown): node is NodeList {
  return Object.prototype.toString.call(node) === '[object NodeList]'
}

export function isMinimalSpan(node: TypedObject): node is MinimalSpan {
  return node._type === 'span'
}

export function isMinimalBlock(node: TypedObject): node is MinimalBlock {
  return node._type === 'block'
}

export function isPlaceholderDecorator(
  node: TypedObject,
): node is PlaceholderDecorator {
  return node._type === '__decorator'
}

export function isPlaceholderAnnotation(
  node: TypedObject,
): node is PlaceholderAnnotation {
  return node._type === '__annotation'
}

/**
 * Matches inline `font-family` declarations that signal code: either the
 * generic `monospace` keyword (Google Docs always appends it to its code
 * fonts, e.g. `font-family:'Roboto Mono',monospace`) or a well-known
 * monospace font name for sources that omit the generic fallback.
 */
const MONOSPACE_FONT_FAMILY_REGEX =
  /font-family\s*:[^;]*(?:\bmonospace\b|courier|consolas|menlo|monaco|roboto mono|source code pro|fira code|fira mono|jetbrains mono|ibm plex mono|ubuntu mono)/i

/**
 * Returns true when the element's inline `style` declares a monospace
 * font-family. This is the only signal Google Docs emits for code: it has no
 * semantic code markup, a code paragraph is just a `<p>` whose spans carry
 * `font-family:'Roboto Mono',monospace`.
 */
export function hasMonospaceFontFamily(el: Node): boolean {
  const style = isElement(el) && el.getAttribute('style')
  return style ? MONOSPACE_FONT_FAMILY_REGEX.test(style) : false
}

/**
 * Returns true when the element's inline `style` declares a whitespace-
 * preserving `white-space`. Google Docs sets `white-space:pre-wrap` on its
 * spans; sources that merely use a monospace font without it (e.g. Word's
 * `font-family:"Roboto Mono"` spans) wrap their HTML source freely, so
 * their intra-span whitespace is formatting, not content.
 */
export function hasPreservedWhitespaceStyle(el: Node): boolean {
  const style = isElement(el) && el.getAttribute('style')
  return style
    ? /white-space\s*:\s*(?:pre|pre-wrap|break-spaces)/.test(style)
    : false
}

export function isElement(node: Node): node is Element {
  return node.nodeType === 1
}

/**
 * Narrows to `HTMLTableElement` so the scoped `rows`, `cells`, `tHead`, and
 * `tBodies` collections are available: unlike `querySelectorAll`, they stop
 * at the table's own structure and never reach into a nested table.
 */
export function isTableElement(node: Node): node is HTMLTableElement {
  return isElement(node) && tagName(node) === 'table'
}
